package com.github.jerpent.bankcleaner;

import lombok.Value;

@Value
public class RedundantItem
{
	public enum Category
	{
		SELL,       // tradeable + outclassed
		DROP,       // untradeable + outclassed
		DEGRADEABLE // needs manual review
	}

	int itemId;
	String name;
	String reason;          // e.g. "Outclassed by Abyssal whip"
	String dominatedBy;     // name of the better item, null for DEGRADEABLE
	String statComparison;  // HTML string showing differing stats, null for DEGRADEABLE
	Category category;
	boolean ignored;
}

package com.github.jerpent.bankcleaner;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bankcleaner")
public interface BankCleanerConfig extends Config
{
	@ConfigItem(
		keyName = "showUntradeables",
		name = "Show untradeables",
		description = "Flag untradeable items that are outclassed by better gear in your bank"
	)
	default boolean showUntradeables()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showDegradeables",
		name = "Show degradeables",
		description = "Show degradeable items that may need review"
	)
	default boolean showDegradeables()
	{
		return true;
	}

	@ConfigItem(
		keyName = "ignoredItemIds",
		name = "Ignored item IDs",
		description = "Comma-separated list of item IDs to hide from results"
	)
	default String ignoredItemIds()
	{
		return "";
	}

	@ConfigItem(
		keyName = "showIgnoredItems",
		name = "Show ignored items",
		description = "Show ignored items with strikethrough instead of hiding them"
	)
	default boolean showIgnoredItems()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showStatComparison",
		name = "Detailed stat tooltip",
		description = "Show a stat-by-stat comparison in the tooltip instead of just the item name"
	)
	default boolean showStatComparison()
	{
		return false;
	}
}

package com.github.jerpent.bankcleaner;

import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.stream.Collectors;

public class BankCleanerPanel extends PluginPanel
{
	private final BankCleanerPlugin plugin;
	private final BankCleanerConfig config;

	private final JLabel statusLabel = new JLabel("Open your bank to scan.");
	private final JPanel sellSection = new JPanel();
	private final JPanel dropSection = new JPanel();
	private final JPanel degradeSection = new JPanel();

	private boolean showIgnored = false;
	private List<RedundantItem> lastItems;
	private boolean lastShowUntradeables;
	private boolean lastShowDegradeables;

	public BankCleanerPanel(BankCleanerPlugin plugin, BankCleanerConfig config)
	{
		this.plugin = plugin;
		this.config = config;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel controls = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		controls.setAlignmentX(Component.LEFT_ALIGNMENT);

		JToggleButton toggleIgnored = new JToggleButton("Show Ignored");
		toggleIgnored.setFont(toggleIgnored.getFont().deriveFont(10f));
		toggleIgnored.addActionListener(e ->
		{
			showIgnored = toggleIgnored.isSelected();
			if (lastItems != null)
			{
				SwingUtilities.invokeLater(() -> renderItems(lastItems, lastShowUntradeables, lastShowDegradeables));
			}
		});

		JButton clearIgnored = new JButton("Clear Ignored");
		clearIgnored.setFont(clearIgnored.getFont().deriveFont(10f));
		clearIgnored.addActionListener(e ->
		{
			plugin.clearIgnoredItems();
			if (lastItems != null)
			{
				lastItems = lastItems.stream()
					.map(i -> new RedundantItem(i.getItemId(), i.getName(), i.getReason(),
						i.getDominatedBy(), i.getStatComparison(), i.getCategory(), false))
					.collect(Collectors.toList());
				SwingUtilities.invokeLater(() -> renderItems(lastItems, lastShowUntradeables, lastShowDegradeables));
			}
		});

		controls.add(toggleIgnored);
		controls.add(clearIgnored);

		statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(statusLabel);
		add(Box.createVerticalStrut(4));
		add(controls);
		add(Box.createVerticalStrut(10));

		add(buildSection("Sell", Color.decode("#c0392b"), sellSection));
		add(Box.createVerticalStrut(8));
		add(buildSection("Drop / Destroy", Color.decode("#e67e22"), dropSection));
		add(Box.createVerticalStrut(8));
		add(buildSection("Degradeables (Review)", Color.decode("#2980b9"), degradeSection));
	}

	private JPanel buildSection(String title, Color color, JPanel contentPanel)
	{
		JPanel wrapper = new JPanel();
		wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel header = new JLabel(title);
		header.setForeground(color);
		header.setFont(header.getFont().deriveFont(Font.BOLD));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrapper.add(header);

		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrapper.add(contentPanel);

		return wrapper;
	}

	public void update(List<RedundantItem> items, boolean showUntradeables, boolean showDegradeables)
	{
		lastItems = items;
		lastShowUntradeables = showUntradeables;
		lastShowDegradeables = showDegradeables;
		SwingUtilities.invokeLater(() -> renderItems(items, showUntradeables, showDegradeables));
	}

	private void renderItems(List<RedundantItem> items, boolean showUntradeables, boolean showDegradeables)
	{
		sellSection.removeAll();
		dropSection.removeAll();
		degradeSection.removeAll();

		int sellCount = 0, dropCount = 0, degradeCount = 0;

		for (RedundantItem item : items)
		{
			if (item.isIgnored() && !showIgnored) continue;

			switch (item.getCategory())
			{
				case SELL:
					addRow(sellSection, item);
					sellCount++;
					break;
				case DROP:
					if (showUntradeables)
					{
						addRow(dropSection, item);
						dropCount++;
					}
					break;
				case DEGRADEABLE:
					if (showDegradeables)
					{
						addRow(degradeSection, item);
						degradeCount++;
					}
					break;
			}
		}

		if (sellCount == 0) addEmpty(sellSection);
		if (showUntradeables && dropCount == 0) addEmpty(dropSection);
		if (showDegradeables && degradeCount == 0) addEmpty(degradeSection);

		int total = sellCount + dropCount + degradeCount;
		statusLabel.setText(total == 0 ? "No redundant items found." : total + " item(s) flagged.");

		revalidate();
		repaint();
	}

	private void addRow(JPanel panel, RedundantItem item)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Build tooltip text — read config live so toggling takes effect without re-scan
		String tooltipText = null;
		if (!item.isIgnored() && item.getReason() != null)
		{
			tooltipText = (config.showStatComparison() && item.getStatComparison() != null)
				? item.getStatComparison()
				: item.getReason();
		}

		// Name line
		String nameText = item.isIgnored()
			? "<html><strike>" + item.getName() + "</strike></html>"
			: "- " + item.getName();
		JLabel nameLabel = new JLabel(nameText);
		if (item.isIgnored()) nameLabel.setForeground(Color.GRAY);
		nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		nameLabel.setToolTipText(tooltipText);

		row.add(nameLabel);

		// Reason sub-line (only when not ignored)
		if (item.getReason() != null && !item.isIgnored())
		{
			JLabel reasonLabel = new JLabel("  " + item.getReason());
			reasonLabel.setForeground(Color.GRAY);
			reasonLabel.setFont(reasonLabel.getFont().deriveFont(10f));
			reasonLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
			reasonLabel.setToolTipText(tooltipText);
			row.add(reasonLabel);
			addPopupListener(reasonLabel, item);
		}

		addPopupListener(nameLabel, item);
		addPopupListener(row, item);

		panel.add(row);
		panel.add(Box.createVerticalStrut(4));
	}

	private void addPopupListener(JComponent component, RedundantItem item)
	{
		JPopupMenu menu = new JPopupMenu();
		if (item.isIgnored())
		{
			JMenuItem unignore = new JMenuItem("Unignore");
			unignore.addActionListener(e ->
			{
				plugin.unignoreItem(item.getItemId());
				updateIgnoreState(item.getItemId(), false);
			});
			menu.add(unignore);
		}
		else
		{
			JMenuItem ignore = new JMenuItem("Ignore");
			ignore.addActionListener(e ->
			{
				plugin.ignoreItem(item.getItemId());
				updateIgnoreState(item.getItemId(), true);
			});
			menu.add(ignore);
		}

		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (e.isPopupTrigger()) menu.show(e.getComponent(), e.getX(), e.getY());
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (e.isPopupTrigger()) menu.show(e.getComponent(), e.getX(), e.getY());
			}
		});
	}

	private void updateIgnoreState(int itemId, boolean ignored)
	{
		if (lastItems == null) return;
		lastItems = lastItems.stream()
			.map(i -> i.getItemId() == itemId
				? new RedundantItem(i.getItemId(), i.getName(), i.getReason(),
					i.getDominatedBy(), i.getStatComparison(), i.getCategory(), ignored)
				: i)
			.collect(Collectors.toList());
		SwingUtilities.invokeLater(() -> renderItems(lastItems, lastShowUntradeables, lastShowDegradeables));
	}

	private void addEmpty(JPanel panel)
	{
		JLabel none = new JLabel("None");
		none.setForeground(Color.GRAY);
		none.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.add(none);
	}

	public void reset()
	{
		SwingUtilities.invokeLater(() ->
		{
			sellSection.removeAll();
			dropSection.removeAll();
			degradeSection.removeAll();
			statusLabel.setText("Open your bank to scan.");
			lastItems = null;
			revalidate();
			repaint();
		});
	}
}

package com.github.jerpent.bankcleaner;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

@Slf4j
@PluginDescriptor(
	name = "Bank Cleaner",
	description = "Identifies redundant gear in your bank",
	tags = {"bank", "gear", "cleanup", "inventory"}
)
public class BankCleanerPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ItemClassifier classifier;

	@Inject
	private ItemComparator comparator;

	@Inject
	private BankCleanerConfig config;

	@Inject
	private ConfigManager configManager;

	private BankCleanerPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		panel = new BankCleanerPanel(this, config);

		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		// Handle
		g.setColor(new Color(139, 90, 43));
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawLine(13, 0, 5, 8);
		// Ferrule band
		g.setColor(new Color(80, 50, 10));
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawLine(6, 7, 4, 9);
		// Bristles
		g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(220, 180, 80));
		g.drawLine(5, 9,  0, 15);
		g.drawLine(5, 9,  2, 15);
		g.drawLine(5, 9,  4, 15);
		g.drawLine(5, 9,  6, 15);
		g.drawLine(5, 9,  8, 15);
		g.dispose();

		navButton = NavigationButton.builder()
			.tooltip("Bank Cleaner")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel.reset();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.BANK)
		{
			return;
		}

		ItemContainer bank = event.getItemContainer();
		if (bank == null) return;

		scanBank(bank.getItems());
	}

	private void scanBank(Item[] items)
	{
		Set<Integer> ignored = getIgnoredIds();
		List<BankItem> equippable = new ArrayList<>();
		List<RedundantItem> degradeables = new ArrayList<>();

		for (Item item : items)
		{
			if (item.getId() <= 0) continue;

			String name = itemManager.getItemComposition(item.getId()).getName();

			if (classifier.isDegradeable(item.getId(), name) && config.showDegradeables())
			{
				degradeables.add(new RedundantItem(
					item.getId(), name,
					"Degradeable item — verify you need this in your bank",
					null,
					null,
					RedundantItem.Category.DEGRADEABLE,
					ignored.contains(item.getId())
				));
				continue;
			}

			if (!classifier.isEquippable(item.getId())) continue;

			ItemStats stats = classifier.getStats(item.getId());
			if (stats == null || stats.getEquipment() == null) continue;
			if (!comparator.hasAnyStats(stats)) continue; // skip cosmetic items with all-zero stats

			boolean tradeable = classifier.isTradeable(item.getId());
			ItemClassifier.WeaponSubtype subtype = classifier.getWeaponSubtype(item.getId(), name);
			equippable.add(new BankItem(item.getId(), name, stats, tradeable, subtype));
		}

		List<RedundantItem> results = new ArrayList<>();

		for (int i = 0; i < equippable.size(); i++)
		{
			BankItem candidate = equippable.get(i);

			for (int j = 0; j < equippable.size(); j++)
			{
				if (i == j) continue;
				BankItem other = equippable.get(j);

				if (comparator.isDominatedBy(candidate.stats, other.stats, candidate.subtype, other.subtype))
				{
					RedundantItem.Category category = candidate.tradeable
						? RedundantItem.Category.SELL
						: RedundantItem.Category.DROP;

					String statComparison = comparator.buildStatComparison(candidate.stats, other.stats, other.name);

					results.add(new RedundantItem(
						candidate.id,
						candidate.name,
						"Outclassed by " + other.name,
						other.name,
						statComparison,
						category,
						ignored.contains(candidate.id)
					));
					break;
				}
			}
		}

		results.addAll(degradeables);
		panel.update(results, config.showUntradeables(), config.showDegradeables());
	}

	public void ignoreItem(int itemId)
	{
		Set<Integer> ids = getIgnoredIds();
		ids.add(itemId);
		saveIgnoredIds(ids);
	}

	public void unignoreItem(int itemId)
	{
		Set<Integer> ids = getIgnoredIds();
		ids.remove(itemId);
		saveIgnoredIds(ids);
	}

	public void clearIgnoredItems()
	{
		configManager.setConfiguration("bankcleaner", "ignoredItemIds", "");
	}

	public Set<Integer> getIgnoredIds()
	{
		String raw = config.ignoredItemIds();
		if (raw == null || raw.isBlank()) return new HashSet<>();
		return Arrays.stream(raw.split(","))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.map(Integer::parseInt)
			.collect(Collectors.toCollection(HashSet::new));
	}

	private void saveIgnoredIds(Set<Integer> ids)
	{
		String value = ids.stream().map(String::valueOf).collect(Collectors.joining(","));
		configManager.setConfiguration("bankcleaner", "ignoredItemIds", value);
	}

	private static class BankItem
	{
		final int id;
		final String name;
		final ItemStats stats;
		final boolean tradeable;
		final ItemClassifier.WeaponSubtype subtype;

		BankItem(int id, String name, ItemStats stats, boolean tradeable, ItemClassifier.WeaponSubtype subtype)
		{
			this.id = id;
			this.name = name;
			this.stats = stats;
			this.tradeable = tradeable;
			this.subtype = subtype;
		}
	}

	@Provides
	BankCleanerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankCleanerConfig.class);
	}
}

package com.github.jerpent.bankcleaner;

import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.ItemEquipmentStats;

import javax.inject.Inject;

public class ItemClassifier
{
	public enum WeaponSubtype
	{
		BOW, CROSSBOW, THROWN, STAFF, MELEE, NONE
	}

	// Weapon slot index in OSRS
	private static final int WEAPON_SLOT = 3;

	@Inject
	private ItemManager itemManager;

	public boolean isTradeable(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp.isTradeable();
	}

	public boolean isDegradeable(int itemId, String name)
	{
		return DegradeableItems.IDS.contains(itemId) || DegradeableItems.isBarrowsVariant(name);
	}

	public boolean isEquippable(int itemId)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		return stats != null && stats.isEquipable();
	}

	public ItemStats getStats(int itemId)
	{
		return itemManager.getItemStats(itemId);
	}

	/**
	 * Returns a weapon subtype for items in the weapon slot.
	 * Non-weapon slots always return NONE.
	 */
	public WeaponSubtype getWeaponSubtype(int itemId, String name)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null || stats.getEquipment() == null) return WeaponSubtype.NONE;
		if (stats.getEquipment().getSlot() != WEAPON_SLOT) return WeaponSubtype.NONE;

		String lower = name.toLowerCase();

		if (lower.contains("crossbow"))                                          return WeaponSubtype.CROSSBOW;
		if (lower.contains("bow") && !lower.contains("elbow"))                  return WeaponSubtype.BOW;
		if (lower.contains("dart") || lower.contains("knife")
			|| lower.contains("javelin") || lower.contains("thrownaxe")
			|| lower.contains("chinchompa") || lower.contains("blowpipe")
			|| lower.contains("ballista"))                                       return WeaponSubtype.THROWN;
		if (lower.contains("staff") || lower.contains("wand")
			|| lower.contains("trident") || lower.contains("sceptre"))          return WeaponSubtype.STAFF;

		return WeaponSubtype.MELEE;
	}
}

package com.github.jerpent.bankcleaner;

import net.runelite.client.game.ItemStats;
import net.runelite.client.game.ItemEquipmentStats;

import java.util.ArrayList;
import java.util.List;

/**
 * Compares two equippable items by their combat stats.
 * Item A is considered redundant if item B is >= in every stat
 * and strictly > in at least one.
 *
 * Attack speed is included with inverted sign (lower tick = faster = better).
 * Weapon subtype must match for weapon-slot items.
 */
public class ItemComparator
{
	/**
	 * Returns true if `other` strictly dominates `item`.
	 * subtypeA and subtypeB must match for weapon-slot items.
	 */
	public boolean isDominatedBy(ItemStats item, ItemStats other,
		ItemClassifier.WeaponSubtype subtypeA, ItemClassifier.WeaponSubtype subtypeB)
	{
		if (item == null || other == null) return false;
		if (!item.isEquipable() || !other.isEquipable()) return false;

		ItemEquipmentStats a = item.getEquipment();
		ItemEquipmentStats b = other.getEquipment();

		if (a == null || b == null) return false;
		if (a.getSlot() != b.getSlot()) return false;

		// Weapons must be the same subtype to be comparable
		if (subtypeA != ItemClassifier.WeaponSubtype.NONE
			&& subtypeB != ItemClassifier.WeaponSubtype.NONE
			&& subtypeA != subtypeB)
		{
			return false;
		}

		boolean anyStrictlyBetter = false;

		int[] statsA = getStats(a);
		int[] statsB = getStats(b);

		for (int i = 0; i < statsA.length; i++)
		{
			if (statsB[i] < statsA[i]) return false;
			if (statsB[i] > statsA[i]) anyStrictlyBetter = true;
		}

		return anyStrictlyBetter;
	}

	/**
	 * Builds an HTML tooltip string showing only the stats where `other` beats `item`.
	 */
	public String buildStatComparison(ItemStats item, ItemStats other, String otherName)
	{
		if (item == null || other == null) return null;
		ItemEquipmentStats a = item.getEquipment();
		ItemEquipmentStats b = other.getEquipment();
		if (a == null || b == null) return null;

		String[] labels = {
			"Stab atk", "Slash atk", "Crush atk", "Magic atk", "Range atk",
			"Stab def", "Slash def", "Crush def", "Magic def", "Range def",
			"Strength", "Range str", "Magic dmg", "Prayer", "Speed"
		};
		int[] statsA = getStats(a);
		int[] statsB = getStats(b);

		List<String> diffs = new ArrayList<>();
		for (int i = 0; i < statsA.length; i++)
		{
			if (statsB[i] > statsA[i])
			{
				// Speed is stored negated — display the real tick values
				if (i == 14)
				{
					diffs.add(String.format("%s: %d vs %d ticks", labels[i], -statsA[i], -statsB[i]));
				}
				else
				{
					diffs.add(String.format("%s: %d vs %d", labels[i], statsA[i], statsB[i]));
				}
			}
		}

		if (diffs.isEmpty()) return otherName + " beats this item";

		StringBuilder sb = new StringBuilder("<html><b>" + otherName + " is better:</b><br>");
		for (String diff : diffs)
		{
			sb.append("&nbsp;").append(diff).append("<br>");
		}
		sb.append("</html>");
		return sb.toString();
	}

	/**
	 * Returns true if the item has at least one non-zero combat stat.
	 * Items with all zeros are assumed to be cosmetic and skipped.
	 */
	public boolean hasAnyStats(ItemStats stats)
	{
		if (stats == null || stats.getEquipment() == null) return false;
		ItemEquipmentStats s = stats.getEquipment();
		// Exclude aspeed from the check — all equippable items have a speed value
		return s.getAstab() != 0 || s.getAslash() != 0 || s.getAcrush() != 0
			|| s.getAmagic() != 0 || s.getArange() != 0
			|| s.getDstab() != 0 || s.getDslash() != 0 || s.getDcrush() != 0
			|| s.getDmagic() != 0 || s.getDrange() != 0
			|| s.getStr() != 0 || s.getRstr() != 0 || s.getMdmg() != 0 || s.getPrayer() != 0;
	}

	private int[] getStats(ItemEquipmentStats s)
	{
		return new int[]{
			s.getAstab(), s.getAslash(), s.getAcrush(), s.getAmagic(), s.getArange(),
			s.getDstab(), s.getDslash(), s.getDcrush(), s.getDmagic(), s.getDrange(),
			s.getStr(), s.getRstr(), (int) s.getMdmg(), s.getPrayer(),
			-s.getAspeed() // lower tick = faster = better, so negate for comparison
		};
	}
}

